                return
            if len(q1) < Y:
                print("No")
                return
            if q1[Y-1] != i + X + Y - 1:
                print("No")
                return

            # Apply operation A
            for _ in range(X):
                q0.popleft()
            for k in range(Y):
                q0.append(i + X + k)
            for k in range(X):
                q1.append(i + k)
