    out_lines = []
    for val in A:
        best = 1
        d = 1
        while d * d <= val:
            if val % d == 0:
                if cnt[d] >= K and d > best:
                    best = d
                other = val // d
                if other != d and cnt[other] >= K and other > best:
                    best = other
            d += 1
        out_lines.append(str(best))

    sys.stdout.write("\n".join(out_lines))

