                        for idx2 in range(l2):
                            v2 = g_arr[idx2]
                            if v2 == 0:
                                continue
                            res[idx1+idx2] = (res[idx1+idx2] - coeff * v1 % P * v2) % P
            # Normalize
            for idx in range(len(res)):
                res[idx] %= P
            D[(I, J)] = res

    final = D[(k, k)]
    mult = Cn[N-1][k-1]

    max_m = N * (N - 1) // 2
